import hashlib
import hmac
import os
import time
import unicodedata
from urllib.parse import unquote

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '').encode()
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET_KEY must be set')

# Blocked paths that require elevated privileges
BLOCKED_PATHS = frozenset([
    '/admin/config',
    '/admin/users',
    '/admin/secrets',
    '/internal/metrics',
    '/internal/debug',
])

ADMIN_ROLES = frozenset(['admin', 'superuser'])

def compute_signature(session_id: str, username: str, role: str, expires: int) -> str:
    """Compute HMAC signature for session data."""
    msg = f"{session_id}|{username}|{role}|{expires}".encode('utf-8')
    return hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()

def verify_session(session_data: dict) -> bool:
    """Verify session integrity and expiration."""
    required = {'session_id', 'username', 'role', 'expires', 'signature'}
    if not required.issubset(session_data.keys()):
        return False

    expected_sig = compute_signature(
        session_data['session_id'],
        session_data['username'],
        session_data['role'],
        session_data['expires']
    )

    if not hmac.compare_digest(expected_sig, session_data['signature']):
        return False

    if time.time() > session_data['expires']:
        return False

    return True

def normalize_path(raw_path: str) -> str:
    """Normalize a URL path: decode percent-encoding, resolve dots, normalize unicode."""
    # Step 1: URL decode
    decoded = unquote(raw_path)

    # Step 2: Unicode NFC normalization for consistent comparison
    normalized = unicodedata.normalize('NFC', decoded)

    # Step 3: Resolve path traversal
    parts = normalized.split('/')
    resolved = []
    for part in parts:
        if part == '..':
            if resolved:
                resolved.pop()
        elif part and part != '.':
            resolved.append(part)

    return '/' + '/'.join(resolved)

def is_path_blocked(path: str, role: str) -> bool:
    """Check if a path requires admin access."""
    if role in ADMIN_ROLES:
        return False
    return path in BLOCKED_PATHS

def authorize_request(session_data: dict, raw_path: str) -> dict:
    """Main authorization function.

    Returns dict with 'allowed' bool and 'resource' path.
    """
    if not verify_session(session_data):
        return {'allowed': False, 'reason': 'invalid_session', 'resource': None}

    role = session_data['role']

    # Normalize the path for blocklist checking
    check_path = normalize_path(raw_path)

    # Check against blocklist using normalized path
    if is_path_blocked(check_path, role):
        return {'allowed': False, 'reason': 'forbidden', 'resource': None}

    # Use NFKC-normalized version for actual resource resolution
    # This handles compatibility decomposition for filesystem lookup
    resource_path = unicodedata.normalize('NFKC', unquote(raw_path))
    parts = resource_path.split('/')
    resolved = []
    for part in parts:
        if part == '..':
            if resolved:
                resolved.pop()
        elif part and part != '.':
            resolved.append(part)
    resource_path = '/' + '/'.join(resolved)

    return {'allowed': True, 'reason': 'ok', 'resource': resource_path}

def handle_request(session_data: dict, raw_path: str) -> str:
    """Process an incoming request."""
    result = authorize_request(session_data, raw_path)

    if not result['allowed']:
        return f"403 Forbidden: {result['reason']}"

    resource = result['resource']

    # Simulate resource access
    if resource.startswith('/admin/'):
        return f"Admin resource: {resource}"
    elif resource.startswith('/internal/'):
        return f"Internal resource: {resource}"
    else:
        return f"Public resource: {resource}"

def create_session(username: str, role: str, duration: int = 3600) -> dict:
    """Create a new signed session."""
    session_id = os.urandom(16).hex()
    expires = int(time.time()) + duration
    signature = compute_signature(session_id, username, role, expires)
    return {
        'session_id': session_id,
        'username': username,
        'role': role,
        'expires': expires,
        'signature': signature
    }
